// Native `-cO` (nz_optimum2, method_p0==6) LZ/CM engine constant tables.
// See include/nz_optimum2_lz.h for the full RE provenance / architecture
// summary (work/reports/decomp_optimum/optimum_lz_core_ARCHITECTURE.md is the
// primary source doc; this port's own additional findings on top of that
// doc's "session 5" section are in nz_optimum2_lz.cpp's header comment).
//
// kOptimum2ColdStateRleB64: a base64 encoding of a trivial RLE compression
// ((byte value, varint run-length) pairs) of the EXACT 0x1083000-byte "large"
// subengine object memory, dumped live via GDB at the very first instruction
// of FUN_080a5d90 (i.e. before any bit is ever decoded for a brand-new
// subengine instance). RLE'd (not embedded raw like the sibling -co port's
// OptimumColdState) because this object is ~17MB (dominated by a 16MB
// order-2 bit-history table and a 256KB LZP-predictor hash table) -- but is
// also extremely repetitive (48651 runs across the whole 17313792 bytes),
// so a trivial RLE shrinks it to ~97KB raw / ~130KB base64, comparable in
// size to the sibling -co port's own embedded blob despite covering a ~50x
// larger object.

#include "nz_optimum2_lz_tables.h"

#include <cstring>

